import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";

// ---------------------------------------------------------------------------
// Security test stubs for: SpecGuard Core – File Reader Abstraction
// Module: specguard-core/reader
// Generated by SpecGuard – OWASP Top 10 annotated
// ---------------------------------------------------------------------------

// Lazy import so individual tests can mock the module before resolution.
let reader: typeof import("../../src/core/reader.js");

beforeEach(async () => {
  vi.resetModules();
  reader = await import("../../src/core/reader.js");
});

afterEach(() => {
  vi.restoreAllMocks();
});

// ---------------------------------------------------------------------------
// Path-Traversal (readFile)
// ---------------------------------------------------------------------------

describe("readFile – path-traversal hardening", () => {
  // OWASP A01: Broken Access Control
  it("should not resolve paths that escape the working directory via ../", async () => {
    const traversalPath = "../../../etc/passwd";
    await expect(reader.readFile(traversalPath)).rejects.toThrow();
  });

  // OWASP A01: Broken Access Control
  it("should not resolve paths that escape via URL-encoded traversal sequences (%2e%2e%2f)", async () => {
    const encodedTraversal = "%2e%2e%2f%2e%2e%2fetc%2fpasswd";
    await expect(reader.readFile(encodedTraversal)).rejects.toThrow();
  });

  // OWASP A01: Broken Access Control
  it("should not resolve paths that escape via double-encoded traversal sequences (%252e%252e%252f)", async () => {
    const doubleEncoded = "%252e%252e%252f%252e%252e%252fetc%252fshadow";
    await expect(reader.readFile(doubleEncoded)).rejects.toThrow();
  });

  // OWASP A01: Broken Access Control
  it("should not resolve absolute paths outside the permitted root", async () => {
    const absolutePath = "/etc/passwd";
    await expect(reader.readFile(absolutePath)).rejects.toThrow();
  });

  // OWASP A01: Broken Access Control
  it("should not resolve Windows-style path-traversal sequences (..\\ variants)", async () => {
    const windowsTraversal = "..\\..\\windows\\system32\\drivers\\etc\\hosts";
    await expect(reader.readFile(windowsTraversal)).rejects.toThrow();
  });

  // OWASP A01: Broken Access Control
  it("should not resolve null-byte injected paths", async () => {
    const nullBytePath = "legitimate-file\x00../../etc/passwd";
    await expect(reader.readFile(nullBytePath)).rejects.toThrow();
  });

  // OWASP A01: Broken Access Control
  it("should not resolve paths with mixed slash traversal (....//....//)", async () => {
    const mixedSlash = "....//....//etc/passwd";
    await expect(reader.readFile(mixedSlash)).rejects.toThrow();
  });

  // OWASP A01: Broken Access Control
  it("should not resolve UNC paths on Windows (\\\\server\\share)", async () => {
    const uncPath = "\\\\attacker-server\\share\\secret";
    await expect(reader.readFile(uncPath)).rejects.toThrow();
  });
});

// ---------------------------------------------------------------------------
// Path-Traversal (fileExists)
// ---------------------------------------------------------------------------

describe("fileExists – path-traversal hardening", () => {
  // OWASP A01: Broken Access Control
  it("should not confirm existence of files outside permitted root via ../", async () => {
    const traversalPath = "../../../etc/passwd";
    const result = await reader.fileExists(traversalPath).catch(() => false);
    expect(result).toBe(false);
  });

  // OWASP A01: Broken Access Control
  it("should not confirm existence of absolute paths outside permitted root", async () => {
    const absolutePath = "/etc/shadow";
    const result = await reader.fileExists(absolutePath).catch(() => false);
    expect(result).toBe(false);
  });

  // OWASP A01: Broken Access Control
  it("should not confirm existence of null-byte injected paths", async () => {
    const nullBytePath = "file\x00../../etc/passwd";
    const result = await reader.fileExists(nullBytePath).catch(() => false);
    expect(result).toBe(false);
  });

  // OWASP A01: Broken Access Control
  it("should not confirm existence of URL-encoded traversal paths", async () => {
    const encodedPath = "%2e%2e%2fetc%2fpasswd";
    const result = await reader.fileExists(encodedPath).catch(() => false);
    expect(result).toBe(false);
  });
});

