// ---------------------------------------------------------------------------
// Sensitive Data Exposure – module must not leak secrets in errors
// ---------------------------------------------------------------------------

describe("readFile – error message information disclosure", () => {
  // OWASP A02: Cryptographic Failures / OWASP A05: Security Misconfiguration
  it("should not expose absolute filesystem paths in thrown error messages", async () => {
    try {
      await reader.readFile("nonexistent-file.txt");
    } catch (err: unknown) {
      if (err instanceof Error) {
        // Error messages must not reveal server-side absolute paths
        expect(err.message).not.toMatch(/^\/(?:home|root|var|usr|etc)\//);
        expect(err.message).not.toMatch(/C:\\Users\\/i);
      }
    }
  });

  // OWASP A02: Cryptographic Failures / OWASP A05: Security Misconfiguration
  it("should not expose internal stack frames referencing sensitive system paths in the error object", async () => {
    try {
      await reader.readFile("../../../etc/passwd");
    } catch (err: unknown) {
      if (err instanceof Error && err.stack) {
        expect(err.stack).not.toMatch(/\/etc\/passwd/);
      }
    }
  });
});

describe("fileExists – error message information disclosure", () => {
  // OWASP A02: Cryptographic Failures / OWASP A05: Security Misconfiguration
  it("should not expose absolute filesystem paths when returning false for traversal paths", async () => {
    let caughtError: Error | undefined;
    try {
      await reader.fileExists("../../../etc/passwd");
    } catch (err: unknown) {
      if (err instanceof Error) {
        caughtError = err;
      }
    }
    if (caughtError) {
      expect(caughtError.message).not.toMatch(/\/etc\/passwd/);
    }
  });
});

// ---------------------------------------------------------------------------
// Denial of Service – resource exhaustion vectors
// ---------------------------------------------------------------------------

describe("readFile – denial-of-service hardening", () => {
  // OWASP A05: Security Misconfiguration
  it("should complete or reject within a reasonable timeout for a deeply nested path", async () => {
    const deepPath = Array(512).fill("dir").join("/") + "/file.txt";
    const raceTimeout = new Promise<never>((_, reject) =>
      setTimeout(() => reject(new Error("timeout")), 5000)
    );
    await expect(
      Promise.race([reader.readFile(deepPath), raceTimeout])
    ).rejects.toThrow();
  });

  // OWASP A05: Security Misconfiguration
  it("should complete or reject within a reasonable timeout for a path with many repeated traversal segments", async () => {
    const manyTraversals = "../".repeat(1000) + "etc/passwd";
    const raceTimeout = new Promise<never>((_, reject) =>
      setTimeout(() => reject(new Error("timeout")), 5000)
    );
    await expect(
      Promise.race([reader.readFile(manyTraversals), raceTimeout])
    ).rejects.toThrow();
  });
});

// ---------------------------------------------------------------------------
// No Authentication / Authorisation – caller responsibility boundary
// ---------------------------------------------------------------------------

describe("module contract – no auth/authz performed internally", () => {
  // OWASP A01: Broken Access Control
  it("readFile should not silently succeed when given a path outside the spec-permitted boundary (caller must enforce)", async () => {
    // The module itself must either enforce boundaries or throw; it must never
    // silently return content for a clearly out-of-bounds path.
    const outOfBounds = "../../secret.env";
    let succeeded = false;
    try {
      await reader.readFile(outOfBounds);
      succeeded = true;
    } catch {
      succeeded = false;
    }
    // If the module has no internal boundary enforcement it MUST throw,
    // ensuring callers cannot accidentally bypass checks.
    expect(succeeded).toBe(false);
  });

  // OWASP A01: Broken Access Control
  it("fileExists should not silently return true for a path outside the spec-permitted boundary", async () => {
    const outOfBounds = "../../secret.env";
    let result: boolean | undefined;
    try {
      result = await reader.fileExists(outOfBounds);
    } catch {
      result = false;
    }
    expect(result).toBe(false);
  });
});
